function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 3 || nums.length > 1000) return 'nums needs 3 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is a whole number between 1 and 10^9.';
  let low = nums[0];
  let suffixLow = new Array(nums.length).fill(Infinity);
  for (let i = nums.length - 2; i >= 0; i--) suffixLow[i] = Math.min(suffixLow[i + 1], nums[i + 1]);
  for (let i = 1; i < nums.length - 1; i++) {
    if (low < nums[i] && suffixLow[i] < nums[i]) return null;
    low = Math.min(low, nums[i]);
  }
  return 'Some value needs a smaller value on each side so that a mountain can be made.';
}

