function minimumMountainRemovals(nums) {
  function risingLengths(values) {
    const tails = [];
    const lengths = [];
    for (const value of values) {
      let left = 0;
      let right = tails.length;
      while (left < right) {
        const mid = (left + right) >> 1;
        if (tails[mid] < value) {
          left = mid + 1;
        } else {
          right = mid;
        }
      }
      tails[left] = value;
      lengths.push(left + 1);
    }
    return lengths;
  }

  const n = nums.length;
  const up = risingLengths(nums);
  const down = risingLengths([...nums].reverse()).reverse();
  let longest = 0;
  for (let i = 1; i < n - 1; i++) {
    if (up[i] > 1 && down[i] > 1) {
      longest = Math.max(longest, up[i] + down[i] - 1);
    }
  }
  return n - longest;
}

