function minimumMountainRemovals(nums) {
  // Quadratic DP: best strictly rising run ending at i and strictly falling run starting at i.
  const n = nums.length;
  const inc = new Array(n).fill(1);
  const dec = new Array(n).fill(1);
  for (let i = 0; i < n; i++) for (let j = 0; j < i; j++) if (nums[j] < nums[i]) inc[i] = Math.max(inc[i], inc[j] + 1);
  for (let i = n - 1; i >= 0; i--) for (let j = n - 1; j > i; j--) if (nums[j] < nums[i]) dec[i] = Math.max(dec[i], dec[j] + 1);
  let keep = 0;
  for (let i = 0; i < n; i++) if (inc[i] >= 2 && dec[i] >= 2) keep = Math.max(keep, inc[i] + dec[i] - 1);
  return n - keep;
}

