function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const possible = (nums) => {
    let low = nums[0];
    const suffix = new Array(nums.length).fill(Infinity);
    for (let i = nums.length - 2; i >= 0; i--) suffix[i] = Math.min(suffix[i + 1], nums[i + 1]);
    for (let i = 1; i < nums.length - 1; i++) {
      if (low < nums[i] && suffix[i] < nums[i]) return true;
      low = Math.min(low, nums[i]);
    }
    return false;
  };
  for (;;) {
    const roll = rand();
    const n = size === 'large' ? int(800, 1000) : int(3, 10);
    const top = size === 'large' ? (roll < 0.4 ? 1000000000 : int(5, 300)) : (roll < 0.6 ? 5 : 1000000000);
    const nums = Array.from({ length: n }, () => int(1, top));
    if (size === 'large' && roll > 0.8) {
      // A noisy hill: rising then falling trend with random bumps.
      const peak = int(1, n - 2);
      for (let i = 0; i < n; i++) nums[i] = Math.max(1, 1000 * (n - Math.abs(i - peak)) + int(-3000, 3000));
    }
    if (possible(nums)) return [nums];
  }
}
